 Sección 3 Redes Aleatorias library(reticulate) Ya hemos analizado cómo medimos la estructura de las redes y los métodos matemáticos, estadísticos y computacionales para dar sentido a los datos que obtenemos de nuestras mediciones. Hemos visto, por ejemplo, cómo medir la estructura de Internet y, una vez que la hemos medido, cómo determinar su distribución de grados, su diámetro o la centralidad de sus nodos. Una pregunta evidente que surge es: ``Si sé que una red tiene alguna propiedad particular, como una distribución de grados específica, ¿qué efecto tendrá eso en el comportamiento más amplio del sistema?’’ Resulta que propiedades como las distribuciones de grado pueden, de hecho, tener enormes efectos en los sistemas en red, lo cual es una de las principales razones por las que estamos interesados en ellas. Y una de las mejores maneras de entender y adquirir intuición sobre estos efectos es construir modelos matemáticos. Vamos a ver algunos de los modelos más utilizados de estructura de redes, modelos que imitan los patrones de conexiones en redes. Estos modelos nos permiten crear redes artificiales con parámetros conocidos, lo cual es útil por dos razones: primero, nos proporcionan comprensión sobre preguntas fundamentales de estructura, por qué las redes tienen la forma que tienen y cómo cambian al modificar los parámetros, y segundo, proporcionan una base sobre la cual construir una comprensión de los procesos que tienen lugar en las redes, como la propagación de enfermedades en redes sociales o la búsqueda de información en la Web. 3.1 El Modelo de Erdös Renyi para construir redes aleatorias Vamos a construir una función donde generemos un modelo \(G(N,p)\): cada par de los \(N\) vértices está conectado con probabilidad \(p\). import random import networkx as nx import matplotlib.pyplot as plt def grafo_erdos_renyi(N, p): G = nx.Graph() G.add_nodes_from(range(N)) # agregar aristas con probabilidad p for i in range(N): for j in range(i+1, N): if random.random() &lt; p: # U~Unif(0,1), P(U&lt;p)=p G.add_edge(i, j) return G Con está función, podemos definir los parámetros y realizar una red aleatoria. # parámetros N = 12 p = 1/6 # generar grafo G = grafo_erdos_renyi(N, p) # layout (posición de nodos) pos = nx.spring_layout(G, seed=42) # dibujar plt.figure(figsize=(6,6)) nx.draw(G, pos, with_labels=True, node_color=&quot;lightblue&quot;, edge_color=&quot;gray&quot;) # guardar imagen plt.savefig(&quot;grafo_erdos_renyi.png&quot;, dpi=300) # mostrar plt.show() Networkx ya tiene implementada la función de un grafo de Erdös Renyi. N = 20 # número de nodos p = 0.2 # probabilidad de conexión G = nx.erdos_renyi_graph(n=N, p=p) # visualizar nx.draw(G, with_labels=True) plt.show() 3.1.1 Distribución de grado from scipy.stats import binom, poisson # Parámetro: grado medio deseado k_mean = 50 # Valores de N Ns = [10**2, 10**3, 10**4] # Rango de k para graficar k_vals = np.arange(20, 81) plt.figure(figsize=(8, 5)) # --- Curva Poisson teórica --- poisson_pmf = poisson.pmf(k_vals, mu=k_mean) plt.plot(k_vals, poisson_pmf, &#39;--&#39;, lw=2, label=&#39;POISSON&#39;) # --- Curva binomial teórica --- # Para comparar, usamos N grande (por ejemplo 10^4) N_ref = 10**4 p_ref = k_mean / (N_ref - 1) binom_pmf = binom.pmf(k_vals, N_ref - 1, p_ref) plt.plot(k_vals, binom_pmf, &#39;-&#39;, lw=2, label=&#39;BINOMIAL&#39;) # --- &quot;Datos&quot; para distintos N --- markers = [&#39;^&#39;, &#39;o&#39;, &#39;v&#39;] for N, marker in zip(Ns, markers): p = k_mean / (N - 1) # Muestreamos grados directamente de Binomial(N-1, p) # Esto representa los grados de los nodos en G(N,p) grados = np.random.binomial(N - 1, p, size=50000) # Histograma normalizado probs = np.array([(grados == k).mean() for k in k_vals]) plt.plot( k_vals, probs, linestyle=&#39;None&#39;, marker=marker, markersize=5, label=fr&#39;N=$10^{int(np.log10(N))}$&#39; ) plt.xlabel(&#39;k&#39;, fontsize=12) plt.ylabel(r&#39;$p_k$&#39;, fontsize=12) plt.xlim(20, 80) ## (20.0, 80.0) plt.ylim(0, 0.10) ## (0.0, 0.1) plt.legend(frameon=False) plt.tight_layout() plt.savefig(&quot;distribucion_grado_red_aleatoria.png&quot;, dpi=300) plt.show() 3.1.2 Número de Aristas Veamos que para mismos parámetros, las realizaciones de una red aleatoria nos dan distintos números de aristas. def grafo_erdos_renyi(N, p, seed=None): &quot;&quot;&quot; Genera una realización del grafo aleatorio G(N,p). &quot;&quot;&quot; if seed is not None: random.seed(seed) G = nx.Graph() G.add_nodes_from(range(N)) for i in range(N): for j in range(i + 1, N): if random.random() &lt; p: G.add_edge(i, j) return G def dibujar_realizaciones(N, p, n_realizaciones=3, layout=&quot;spring&quot;, seed_base=10): &quot;&quot;&quot; Dibuja varias realizaciones de G(N,p) con los mismos parámetros. &quot;&quot;&quot; fig, axes = plt.subplots(1, n_realizaciones, figsize=(5 * n_realizaciones, 5)) if n_realizaciones == 1: axes = [axes] for k, ax in enumerate(axes): G = grafo_erdos_renyi(N, p, seed=seed_base + k) # Elegir layout if layout == &quot;circular&quot;: pos = nx.circular_layout(G) else: pos = nx.spring_layout(G, seed=seed_base + k) L = G.number_of_edges() nx.draw_networkx_nodes( G, pos, ax=ax, node_size=300, node_color=&quot;#7a4fa3&quot; ) nx.draw_networkx_edges( G, pos, ax=ax, edge_color=&quot;limegreen&quot;, width=1.5 ) ax.set_title(f&quot;Realización {k+1}
